"""Synchronous LND gRPC client (stubs generated by scripts/gen_protos.sh).

Errors are split into two classes on purpose:
- LndUnavailable: no definitive answer (connection refused/reset, deadline exceeded,
  LND starting up...). The call MAY have been executed. Callers must treat the
  outcome as unknown and re-derive state from LND on the next attempt.
- LndError: LND answered and explicitly rejected the call. It did not happen.

The swap state machine is designed so that misclassifying one as the other can
never move funds wrongly; at worst it refunds a payer or halts the service.
"""
import os
import threading
from typing import Optional

import grpc

from app.config import settings
from app.lnrpc import lightning_pb2 as ln
from app.lnrpc import lightning_pb2_grpc as ln_grpc
from app.lnrpc.invoicesrpc import invoices_pb2 as inv
from app.lnrpc.invoicesrpc import invoices_pb2_grpc as inv_grpc
from app.lnrpc.walletrpc import walletkit_pb2 as wk
from app.lnrpc.walletrpc import walletkit_pb2_grpc as wk_grpc

# Status codes that LND uses for application-level rejections. Anything else
# (UNAVAILABLE, DEADLINE_EXCEEDED, CANCELLED, INTERNAL, ...) is treated as ambiguous.
_DEFINITIVE_CODES = {
    grpc.StatusCode.UNKNOWN,  # plain Go errors from LND ("insufficient funds ...")
    grpc.StatusCode.INVALID_ARGUMENT,
    grpc.StatusCode.NOT_FOUND,
    grpc.StatusCode.ALREADY_EXISTS,
    grpc.StatusCode.FAILED_PRECONDITION,
    grpc.StatusCode.OUT_OF_RANGE,
    grpc.StatusCode.PERMISSION_DENIED,
    grpc.StatusCode.UNAUTHENTICATED,
    grpc.StatusCode.UNIMPLEMENTED,
}

InvoiceState = ln.Invoice.InvoiceState


class LndUnavailable(Exception):
    pass


class LndError(Exception):
    def __init__(self, code: grpc.StatusCode, message: str, method: str):
        super().__init__(f"LND {method} -> {code.name}: {message}")
        self.code = code
        self.message = message
        self.method = method


class _MacaroonAuth(grpc.AuthMetadataPlugin):
    def __init__(self, macaroon_hex: str):
        self._macaroon_hex = macaroon_hex

    def __call__(self, context, callback):
        callback((("macaroon", self._macaroon_hex),), None)


class LndClient:
    def __init__(
        self,
        host: Optional[str] = None,
        macaroon_path: Optional[str] = None,
        tls_cert_path: Optional[str] = None,
        tls_server_name: Optional[str] = None,
        timeout: float = 30.0,
    ):
        self.host = host or settings.LND_GRPC_HOST
        self.macaroon_path = macaroon_path or settings.LND_MACAROON_PATH
        self.tls_cert_path = tls_cert_path or settings.LND_TLS_CERT_PATH
        self.tls_server_name = tls_server_name or settings.LND_TLS_SERVER_NAME
        self.timeout = timeout
        self._channel: Optional[grpc.Channel] = None
        self._init_lock = threading.Lock()

    def _stubs(self):
        with self._init_lock:
            if self._channel is None:
                # Fail closed: never talk to LND without verifying its TLS cert.
                if not os.path.isfile(self.tls_cert_path):
                    raise FileNotFoundError(f"LND TLS cert not found at {self.tls_cert_path}")
                if not os.path.isfile(self.macaroon_path):
                    raise FileNotFoundError(f"LND macaroon not found at {self.macaroon_path}")
                with open(self.tls_cert_path, "rb") as f:
                    cert = f.read()
                with open(self.macaroon_path, "rb") as f:
                    macaroon_hex = f.read().hex()
                creds = grpc.composite_channel_credentials(
                    grpc.ssl_channel_credentials(root_certificates=cert),
                    grpc.metadata_call_credentials(_MacaroonAuth(macaroon_hex)),
                )
                options = [("grpc.max_receive_message_length", 50 * 1024 * 1024)]
                if self.tls_server_name:
                    options.append(("grpc.ssl_target_name_override", self.tls_server_name))
                # grpc channels and stubs are thread-safe.
                self._channel = grpc.secure_channel(self.host, creds, options=options)
                self._ln = ln_grpc.LightningStub(self._channel)
                self._inv = inv_grpc.InvoicesStub(self._channel)
                self._wk = wk_grpc.WalletKitStub(self._channel)
            return self._ln, self._inv, self._wk

    def _call(self, method, request, name: str, timeout: Optional[float] = None):
        try:
            return method(request, timeout=timeout or self.timeout)
        except grpc.RpcError as e:
            code = e.code()
            details = e.details() or ""
            if code in _DEFINITIVE_CODES:
                raise LndError(code, details, name) from None
            raise LndUnavailable(f"{name}: {code.name}: {details}") from None

    def close(self):
        with self._init_lock:
            if self._channel is not None:
                self._channel.close()
                self._channel = None

    # --- info / balances ---------------------------------------------------

    def get_info(self) -> ln.GetInfoResponse:
        lnd, _, _ = self._stubs()
        return self._call(lnd.GetInfo, ln.GetInfoRequest(), "GetInfo")

    def wallet_balance(self) -> ln.WalletBalanceResponse:
        lnd, _, _ = self._stubs()
        return self._call(lnd.WalletBalance, ln.WalletBalanceRequest(), "WalletBalance")

    def unconfirmed_txids(self, from_height: int) -> list[str]:
        """Wallet txs (incoming or outgoing, channel txs included) with no confirmation yet.
        Lists from from_height (inclusive) through the tip plus the unconfirmed ones, and
        keeps only the unconfirmed: a block found in between cannot hide anything."""
        lnd, _, _ = self._stubs()
        req = ln.GetTransactionsRequest(start_height=from_height, end_height=-1)
        resp = self._call(lnd.GetTransactions, req, "GetTransactions")
        return [t.tx_hash for t in resp.transactions if t.num_confirmations < 1]

    def estimate_fee_sat_per_kw(self, conf_target: int) -> int:
        _, _, wallet = self._stubs()
        resp = self._call(wallet.EstimateFee, wk.EstimateFeeRequest(conf_target=conf_target), "EstimateFee")
        return int(resp.sat_per_kw)

    def estimate_tx_fee(self, outputs: dict[str, int], conf_target: int, min_confs: int) -> ln.EstimateFeeResponse:
        """Dry run of the payout tx (address -> sat, one output each): LND does the real
        coin selection over the current wallet and returns its fee (at LND's own rate for
        conf_target). Nothing is leased."""
        lnd, _, _ = self._stubs()
        req = ln.EstimateFeeRequest(
            AddrToAmount=dict(outputs),
            target_conf=conf_target,
            min_confs=min_confs,
            spend_unconfirmed=(min_confs == 0),
        )
        return self._call(lnd.EstimateFee, req, "EstimateFee(tx)")

    # --- hold invoices -----------------------------------------------------

    def add_hold_invoice(
        self,
        payment_hash: bytes,
        value_sat: int,
        memo: str,
        expiry_seconds: int,
        cltv_expiry: int,
    ) -> inv.AddHoldInvoiceResp:
        _, invoices, _ = self._stubs()
        req = inv.AddHoldInvoiceRequest(
            hash=payment_hash,
            value=value_sat,
            memo=memo,
            expiry=expiry_seconds,
            cltv_expiry=cltv_expiry,
        )
        return self._call(invoices.AddHoldInvoice, req, "AddHoldInvoice")

    def lookup_invoice(self, payment_hash: bytes) -> ln.Invoice:
        _, invoices, _ = self._stubs()
        return self._call(invoices.LookupInvoiceV2, inv.LookupInvoiceMsg(payment_hash=payment_hash), "LookupInvoiceV2")

    def settle_invoice(self, preimage: bytes) -> None:
        _, invoices, _ = self._stubs()
        self._call(invoices.SettleInvoice, inv.SettleInvoiceMsg(preimage=preimage), "SettleInvoice")

    def cancel_invoice(self, payment_hash: bytes) -> None:
        _, invoices, _ = self._stubs()
        self._call(invoices.CancelInvoice, inv.CancelInvoiceMsg(payment_hash=payment_hash), "CancelInvoice")

    # --- on-chain (walletkit PSBT flow) -------------------------------------

    def fund_psbt(
        self,
        outputs: dict[str, int],
        sat_per_vbyte: int,
        lock_id: bytes,
        lock_expiration_seconds: int,
        min_confs: int,
    ) -> wk.FundPsbtResponse:
        """Pays `outputs` (address -> sat, one output each): selects wallet UTXOs, adds
        change and LEASES the inputs under lock_id. Nothing is signed or broadcast."""
        _, _, wallet = self._stubs()
        req = wk.FundPsbtRequest(
            raw=wk.TxTemplate(outputs=dict(outputs)),
            sat_per_vbyte=sat_per_vbyte,
            min_confs=min_confs,
            spend_unconfirmed=(min_confs == 0),
            custom_lock_id=lock_id,
            lock_expiration_seconds=lock_expiration_seconds,
        )
        return self._call(wallet.FundPsbt, req, "FundPsbt")

    def finalize_psbt(self, funded_psbt: bytes) -> wk.FinalizePsbtResponse:
        """Signs the PSBT and returns the raw final tx. Nothing is broadcast."""
        _, _, wallet = self._stubs()
        return self._call(wallet.FinalizePsbt, wk.FinalizePsbtRequest(funded_psbt=funded_psbt), "FinalizePsbt")

    def publish_transaction(self, raw_tx: bytes, label: str) -> str:
        """Returns publish_error ("" on success). Errors may also come as LndError."""
        _, _, wallet = self._stubs()
        resp = self._call(wallet.PublishTransaction, wk.Transaction(tx_hex=raw_tx, label=label), "PublishTransaction")
        return resp.publish_error


lnd_client = LndClient()
